mat3 rotationMatrix(vec3 axis, float angle)
{
    axis = normalize(axis);
    float s = sin(angle);
    float c = cos(angle);
    float oc = 1.0 - c;

    return mat3(oc * axis.x * axis.x + c,           oc * axis.x * axis.y - axis.z * s,  oc * axis.z * axis.x + axis.y * s,
                oc * axis.x * axis.y + axis.z * s,  oc * axis.y * axis.y + c,           oc * axis.y * axis.z - axis.x * s,
                oc * axis.z * axis.x - axis.y * s,  oc * axis.y * axis.z + axis.x * s,  oc * axis.z * axis.z + c);
}


float sphereIntersectionTime(vec3 rayStart, vec3 rayDir, vec3 center, float radius){
    vec3 pos = rayStart - center;
    float a = dot(rayDir, rayDir);
    float b = 2.f * dot(pos, rayDir);
    float c = dot(pos, pos) - radius * radius;


    float temp = b * b - 4.f * a * c;
    if(temp < 0.f){
        return -1.f;
    }

    return (-b - sqrt(temp)) / (2.f * a);
}


void processWormholes(inout vec3 rayPos, inout vec3 rayDir, vec3 p1, vec3 p2, float radius, float depth, float theta, float phi, float flip){
    float t1 = sphereIntersectionTime(rayPos, rayDir, p1, radius);
    float t2 = sphereIntersectionTime(rayPos, rayDir, p2, radius);

    vec3 intersection1 = rayPos + rayDir * t1;
    vec3 intersection2 = rayPos + rayDir * t2;

    if(t1 > 0.f && t2 > 0.f){
        if(t1 <= t2){
            //enter wormhole side 1
            vec3 toCenter = normalize(p1 - intersection1);

            float parallelDir = dot(toCenter, rayDir);
            vec3 perpDir = rayDir - dot(toCenter, rayDir) * toCenter;

            vec3 angularVelocity = cross(-toCenter, perpDir) / radius;//radians

            float time = depth / parallelDir;

            mat3 rot = rotationMatrix(angularVelocity, length(angularVelocity) * time);

            mat3 rot2 = rotationMatrix(vec3(0, 0, 1), theta) * rotationMatrix(vec3(0, 1, 0), phi);


            rayPos = rot2 * flip * rot * (intersection1 - p1) + p2;

            //rayDir = flip * rot2 * rot * perpDir + normalize(rot2 * flip * rot * (intersection1 - p1)) * parallelDir;

            rayDir = flip * rot2 * rot * reflect(rayDir, toCenter);

        }else{
            //enter wormhole side 2
            vec3 toCenter = normalize(p2 - intersection2);


            float parallelDir = dot(toCenter, rayDir);
            vec3 perpDir = rayDir - dot(toCenter, rayDir) * toCenter;

            vec3 angularVelocity = cross(-toCenter, perpDir) / radius;//radians

            float time = depth / parallelDir;

            mat3 rot = rotationMatrix(angularVelocity, length(angularVelocity) * time);

            mat3 rot2 = rotationMatrix(vec3(0, 1, 0), phi) * rotationMatrix(vec3(0, 0, 1), theta);


            rayPos = rot2 * flip * rot * (intersection2 - p2) + p1;
            rayDir = flip * rot2 * rot * reflect(rayDir, toCenter);

        }
    }else if(t1 > 0.f){
        //enter wormhole side 1
        vec3 toCenter = normalize(p1 - intersection1);


        float parallelDir = dot(toCenter, rayDir);
        vec3 perpDir = rayDir - dot(toCenter, rayDir) * toCenter;

        vec3 angularVelocity = cross(-toCenter, perpDir) / radius;//radians

        float time = depth / parallelDir;

        mat3 rot = rotationMatrix(angularVelocity, length(angularVelocity) * time);

        mat3 rot2 = rotationMatrix(vec3(0, 0, 1), theta) * rotationMatrix(vec3(0, 1, 0), phi);


        rayPos = rot2 * flip * rot * (intersection1 - p1) + p2;

        //rayDir = flip * rot2 * rot * perpDir + normalize(rot2 * flip * rot * (intersection1 - p1)) * parallelDir;

        rayDir = flip * rot2 * rot * reflect(rayDir, toCenter);


    }else if(t2 > 0.f){
        //enter wormhole side 2
        vec3 toCenter = normalize(p2 - intersection2);


        float parallelDir = dot(toCenter, rayDir);
        vec3 perpDir = rayDir - dot(toCenter, rayDir) * toCenter;

        vec3 angularVelocity = cross(-toCenter, perpDir) / radius;//radians

        float time = depth / parallelDir;

        mat3 rot = rotationMatrix(angularVelocity, length(angularVelocity) * time);

        mat3 rot2 = rotationMatrix(vec3(0, 1, 0), phi) * rotationMatrix(vec3(0, 0, 1), theta);


        rayPos = rot2 * flip * rot * (intersection2 - p2) + p1;
        rayDir = flip * rot2 * rot * reflect(rayDir, toCenter);

    }

    rayPos += rayDir * 0.001;

}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    // Normalized pixel coordinates (from 0 to 1)
    vec2 uv = fragCoord/iResolution.xy;
    uv -= 0.5;
    uv.x *= iResolution.x / iResolution.y;


    //Camera Controls
    vec3 camPos = 5.f * vec3(cos(iTime), sin(iTime), 0);
    vec3 camDir = -normalize(camPos);


    vec3 right = cross(camDir, vec3(0,0,1));
    right /= length(right);
    vec3 up = cross(right, camDir);
    up /= length(up);


    vec3 rayPos = camPos;
    vec3 rayDir = camDir + 2.f * (right * uv.x + up * uv.y);


    //Wormhole Controls
    vec3 p1 = vec3(0,2,0);
    vec3 p2 = vec3(0,-2,0);
    float radius = 2.f;
    float depth = radius * 3.1415926589;
    float theta = 0.f;
    float phi = 0.f;
    bool flipChirality = false;
    int maxWormholing = 1;

    //If you set the depth to 0, you get a scenario that is equivalent to a set of spherical portals.

    //this flips the angle phi on one end of the wormhole
    float flip = -1.f;
    if(flipChirality){
        flip = 1.f;
    }

    for(int i = 0; i < maxWormholing; i++){
        processWormholes(rayPos, rayDir, p1, p2, radius, depth, theta, phi, flip);
    }

    vec3 sphere = vec3(4,4,3.f * cos(iTime));
    float sphereRadius = 1.f;
    float hi = sphereIntersectionTime(rayPos.xyz, rayDir.xyz, sphere, sphereRadius);

    if(!isinf(hi) && hi > 0.f){
        fragColor = vec4(normalize((rayPos.xyz + rayDir.xyz * hi) - sphere) * 0.5 + 0.5, 1);
        return;
    }

    // Output to screen
    rayDir = normalize(rayDir);
    vec3 temp = abs(rayDir);
    float maxDir = max(temp.x, max(temp.y, temp.z));
    vec3 maxDirDir = normalize(vec3(equal(vec3(maxDir), temp)) * rayDir);
    vec3 color = 0.5 * (vec3(equal(vec3(maxDir), temp)) + vec3(equal(vec3(maxDir), rayDir)));

    //color = normalize(rayDir) * 0.5 + 0.5;


    fragColor = vec4(color, 1);
}
